mapper.delete:
UPDATE user_follow
SET is_deleted = 1, update_time = NOW()
WHERE follower_id = #{followerId}
  AND followee_id = #{followeeId}
  AND is_deleted = 0

mapper.select:
SELECT CASE WHEN COUNT(DISTINCT f1.followee_id) = #{expectedCount} THEN 1 ELSE 0 END AS all_mutual FROM user_follow f1 INNER JOIN user_follow f2 ON f2.follower_id = f1.followee_id AND f2.followee_id = f1.follower_id AND f2.is_deleted = 0 WHERE f1.follower_id = #{userId} AND f1.followee_id IN
#{id}
AND f1.is_deleted = 0;
